import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        password_hash TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, password_hash) VALUES (1, 'admin', 'admin@corp.internal', 'superadmin', 'pbkdf2:sha256:260000$salt$hash')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, password_hash) VALUES (2, 'svc_backup', 'backup@corp.internal', 'service', 'pbkdf2:sha256:260000$salt2$hash2')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Log the search for compliance
    try:
        db = get_db()
        log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={field} value={value}')"
        db.execute(log_query)
        db.commit()
    except Exception as e:
        app.logger.warning(f"Audit log failed: {e}")

    # Perform the search - field is validated above so safe to interpolate
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE ?"
    try:
        db = get_db()
        results = db.execute(query, (f'%{value}%',)).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>/notes', methods=['PUT'])
def update_notes(user_id):
    """Update user notes/metadata. Internal endpoint."""
    data = request.get_json()
    note = data.get('note', '') if data else ''

    db = get_db()
    # Store note with user reference for admin review
    update_q = f"INSERT INTO audit_log (action, details) VALUES ('note_update', 'user_id={user_id} note={note}')"
    try:
        db.execute(update_q)
        db.commit()
        return jsonify({'status': 'updated'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate filtered user report. Admin only in production."""
    data = request.get_json()
    filters = data.get('filters', {}) if data else {}

    where_clauses = []
    for col, val in filters.items():
        if col in ['username', 'email', 'role']:
            where_clauses.append(f"{col} = '{val}'")

    base_query = "SELECT id, username, email, role FROM users"
    if where_clauses:
        base_query += " WHERE " + " AND ".join(where_clauses)

    try:
        db = get_db()
        results = db.execute(base_query).fetchall()
        return jsonify({'report': [dict(row) for row in results], 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Report generation failed'}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
